('3ede2196-3ab3-4cee-8672-90095c763a3d', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '3855a560-6579-4b80-9638-a8981a7ca48c', '这是一份中文合同文件的照片，主要内容为体系认证服务合同的条款部分，包括：乙方权利与义务、违约责任、保密条款、争议解决方式、合同生效及其他事项等条款。页面下方为甲乙双方签章栏，分别盖有红色印章——甲方印章显示为“重庆星达铜业有限公司合同专用章”，乙方为某企业管理咨询有限公司的合同专用章，并手写填有日期（约2025年11月10日）。', '0', 't', '0', '0', '', '', 'image_caption', '01dd9323-badc-4b08-941f-36b1e8de8881', '[{"url":"resource://iqg4fsQw6lH6ShOg2xANHg","original_url":"resource://iqg4fsQw6lH6ShOg2xANHg","start_pos":0,"end_pos":0,"caption":"这是一份中文合同文件的照片，主要内容为体系认证服务合同的条款部分，包括：乙方权利与义务、违约责任、保密条款、争议解决方式、合同生效及其他事项等条款。页面下方为甲乙双方签章栏，分别盖有红色印章——甲方印章显示为“重庆星达铜业有限公司合同专用章”，乙方为某企业管理咨询有限公司的合同专用章，并手写填有日期（约2025年11月10日）。","ocr_text":"3. 甲方应向乙方提供真实、准确的资料，如因提供虚假资料而产生纠纷或损失（如认证不成功），由甲方自行承担相应责任。\n\n4. 甲方应根据乙方的建议，积极创造条件，采取必要行动，落实乙方的方案和建议，达到上述各体系认证的要求。\n\n**四、乙方权利与义务**\n\n1. 乙方针对甲方的认证体系，成立两人以上的体系认证小组负责甲方体系认证，并提出针对性策划、培育计划、整改目标及实施方案，并指导且协助甲方进行落实。\n\n2. 乙方应根据体系认证要求，协助甲方撰写、收集、整理体系认证材料，并在指定时限内递交认证材料。\n\n3. 乙方应协助甲方准备体系认证的现场检查或验收工作，并将体系认证办理进程告知甲方。\n\n4. 乙方应在体系认证条件发生变化时，及时通知甲方并调整实施方案。\n\n**五、违约责任**\n\n1. 甲方应按本合同约定及时向乙方支付体系认证服务费用，逾期未支付给乙方，此协议即自动解除。\n\n2. 合同签订生效后，非因乙方过错，甲方无故中途取消/终止相应体系认证工作、并在甲方能力范围内（营业执照、开户许可证、法人身份证、土地租赁协议、商业计划书、可行性研究报告、财务报表等资料）不配合乙方有关体系认证工作的，相应风险及服务费用由甲方承担。\n\n3. 乙方向甲方提供的相应体系认证信息或方案，发生以下情形的，视同乙方已成功办理该合同体系，甲方应按本合同第二条约定的费用及支付方式向乙方支付服务费用。\n\n1). 未经乙方书面同意，甲方另行委托其他第三方代为认证或自行认证的；\n\n2). 未经乙方书面同意，甲方另以其关联公司、子公司或第三方公司的名义认证合同体系的。\n\n4. 乙方因泄露或以其他方式侵犯甲方的商业秘密，给甲方造成损失的，乙方应赔偿甲方的经济损失。\n\n**六、保密条款**\n\n甲乙双方对本合同内容及合同履行过程中知悉的双方所有的经营信息、资料等商业秘密负有保密义务，未经对方许可不得自行用于与本合同目的无关的其它事务或向任何第三方泄露、出售、许可使用，但法律要求披露或者通过合法公开途径可获得的除外。\n\n**七、争议解决**\n\n本合同履行过程中产生的一切争议，均应由双方友好协商解决；如协商不成，任何一方均有权向甲方所在地人民法院提起诉讼。\n\n**八、合同生效及其他**\n\n1. 本合同文本规定之条款如有未尽或变更事宜，由双方协商补充，补充协议与本合同具有同等法律效力。\n\n2. 本合同履行和相关事宜的通知，应当按照本合同载明的地址发出。如果以特快专递或挂号信形式寄出，自发出之日起的第四日视为送达。\n\n3. 本合同一式两份，自双方签章之日起生效。甲乙双方各执一份，具有同等法律效力。\n\n甲　方（签章）：\n\n代表人：\n\n日期：　　　年　　月　　日\n\n乙　方（签章）：\n\n代表人：\n\n日期：2025 年 11 月 10 日"}]', NULL, NULL, '2026-09-07 05:17:37.404419+00', '2026-09-07 05:17:38.94245+00', '2026-09-07 07:25:10.074631+00', NULL, '', '2', '', '1', '100000690', NULL, '这是一份中文合同文件的照片，主要内容为体系认证服务合同的条款部分，包括：乙方权利与义务、违约责任、保密条款、争议解决方式、合同生效及其他事项等条款。页面下方为甲乙双方签章栏，分别盖有红色印章——甲方印章显示为“重庆星达铜业有限公司合同专用章”，乙方为某企业管理咨询有限公司的合同专用章，并手写填有日期（约2025年11月10日）。', '0', 'ready', '', ''),
('d4712370-1c0a-4f06-bc95-cd28f9b730bc', '10000', '270af1db-4fd8-43f2-a0e4-dcb823232b95', '12883f27-cd0b-4864-a098-9acaa6c31876', '# Summary
本文件为国家电网重庆市电力公司出具的一份电费账单，账单周期为2026年6月1日至6月30日，打印日期为2026年7月6日。用电户为重庆星达铜业有限公司（户号5001654065328），用电类别为大工业用电，电压等级为交流10kV，用电地址位于重庆市璧山区青杠街道，属市场化零售客户，供电服务单位为璧城供电服务中心，交费截止日期为2026年7月9日。
本期总用电量为645874千瓦时，较上期环比下降3.03%；总电费为464662.87元，其中工商业电费（计费电量636191千瓦时）为462629.35元，居民电费（按定比0.015计得9683千瓦时）为5131.99元，功率因数调整电费为-3098.47元。工商业电费由五部分构成：市场化购电费267499.48元（含零售交易电费277379.27元、零售损益分摊电费-9699.37元及中长期超额申报费用返还-180.42元）、上网环节线损费用11219.23元、输配电费129567.83元（含电量电费85567.83元和按2000千伏安容量、22元电价计收的容量电费44000元）、系统运行费24000.31元（含煤电容量电费、燃气机组容量电费、抽水蓄能容量电费、新能源机制差价分摊电费等，其中电价交叉补贴新增损益为-16760.45元）以及政府性基金及附加30342.5元（含农网还贷、可再生能源附加、库区移民基金等）。
用能分析方面，本期尖峰、峰、平、谷分时电量比例分别为4.86%、19.78%、32.39%、42.97%，与上期相比尖峰和谷占比上升、峰和平占比略降（账单附柱状图直观展示该对比）。实际功率因数为0.97，高于0.9的标准值，较上期提高0.01，故获得电费下调调整。平均电价为0.71943元/千瓦时，较上期下降0.02578元/千瓦时。
账单详情显示，计费电', '9', 't', '0', '0', '', '', 'summary', 'a7d05251-c6ce-43cd-a8e2-1b08b92dba13', '', NULL, NULL, '2026-09-09 09:07:23.40405+00', '2026-09-09 09:07:23.40405+00', NULL, NULL, '', '0', '', '1', '100001055', NULL, '# Summary
本文件为国家电网重庆市电力公司出具的一份电费账单，账单周期为2026年6月1日至6月30日，打印日期为2026年7月6日。用电户为重庆星达铜业有限公司（户号5001654065328），用电类别为大工业用电，电压等级为交流10kV，用电地址位于重庆市璧山区青杠街道，属市场化零售客户，供电服务单位为璧城供电服务中心，交费截止日期为2026年7月9日。
本期总用电量为645874千瓦时，较上期环比下降3.03%；总电费为464662.87元，其中工商业电费（计费电量636191千瓦时）为462629.35元，居民电费（按定比0.015计得9683千瓦时）为5131.99元，功率因数调整电费为-3098.47元。工商业电费由五部分构成：市场化购电费267499.48元（含零售交易电费277379.27元、零售损益分摊电费-9699.37元及中长期超额申报费用返还-180.42元）、上网环节线损费用11219.23元、输配电费129567.83元（含电量电费85567.83元和按2000千伏安容量、22元电价计收的容量电费44000元）、系统运行费24000.31元（含煤电容量电费、燃气机组容量电费、抽水蓄能容量电费、新能源机制差价分摊电费等，其中电价交叉补贴新增损益为-16760.45元）以及政府性基金及附加30342.5元（含农网还贷、可再生能源附加、库区移民基金等）。
用能分析方面，本期尖峰、峰、平、谷分时电量比例分别为4.86%、19.78%、32.39%、42.97%，与上期相比尖峰和谷占比上升、峰和平占比略降（账单附柱状图直观展示该对比）。实际功率因数为0.97，高于0.9的标准值，较上期提高0.01，故获得电费下调调整。平均电价为0.71943元/千瓦时，较上期下降0.02578元/千瓦时。
