第一条 为加强货运车辆安全管理，规范货运车辆运营行为，提高运
输效率，保障人民群众生命财产安全，根据《中华人民共和国道路交
通安全法》、《中华人民共和国道路运输条例》等法律法规，结合本单
位实际情况，制定本制度。
第二条 本制度适用于本单位所有货运车辆及其驾驶员。
第三条 本制度所称 GPS 监管，是指利用全球定位系统（GPS）技术，
对货运车辆进行实时定位、轨迹回放、超速报警、区域限行等监控管
理。
第四条 本单位应建立健全货运车辆 GPS 监管体系，明确责任部门和
人员，配备必要的设备设施，确保 GPS 监管系统正常运行。
第二章 安装与使用
第五条 本单位所有货运车辆必须安装符合国家标准的 GPS 车载终
端，并与本单位 GPS 监管平台联网。
