第三章 监控与管理
第九条 本单位应建立 24 小时值班制度，安排专人负责 GPS 监管平
台的监控管理工作。
第十条 监控人员应实时监控车辆运行状态，及时发现和处理以下情
况：
车辆超速行驶；
车辆偏离预定路线；
车辆进入禁行区域；
车辆长时间停车；
其他异常情况。
第十一条 监控人员发现异常情况，应及时通知驾驶员进行处理，并
做好记录。
第十二条 本单位应定期对 GPS 监管数据进行分析，评估车辆运行状
况，及时发现和解决安全隐患。
第十三条 本单位应建立健全 GPS 监管档案，记录车辆安装、使用、
维护、故障处理等情况。
第四章 责任与处罚
第十四条 驾驶员违反本制度规定，有下列行为之一的，视情节轻重，
给予批评教育、经济处罚、停运整顿等处理：
未按规定安装 GPS 车载终端的；
擅自拆卸、改装、屏蔽 GPS 车载终端的；
