('b174f5a8-8842-4c5a-8412-895dd2dc3de2', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '0b633e9b-347b-4d4d-9036-317bd7f7ae65', '# 重庆北导科技发展有限公司重点运营车辆服务协议
**甲方：** 重庆星达铜业有限公司
**乙方：** 重庆北导科技发展有限公司
甲、乙双方本着诚信原则，经双方友好协商，就甲方车辆安装车载定位监控设备及后续相关服务事宜达成以下协议：
## 一、乙方职责：
1、乙方按照重庆区域主管部门要求，为甲方下属车辆，安装符合：交通部、重庆市运管局要求的车辆安全监控管理设备，并按照相关要求将企业、车辆信息录入对应管理平台，以便甲方车辆正常办理相关营运手续；
2、乙方为甲方免费提供车辆监督管理平台的使用，并负责对平台进行日常维护；
3、乙方负责提供车辆监控终端的日常维护、技术支持、设备维修与质保以及平台系统的免费升级服务；
4、乙方负责车辆动态监控平台的正常运行，并配合甲方及时解决平台运营过程中出现的问题，并对甲方安全管理人员提供相关技术培训。
## 二、甲方职责：
1、甲方负责确保车辆信息的真实性和有效性。如车辆信息发生变更时，要第一时间把更正后的信息提交给乙方并在监控平台上进行修改；', '0', 't', '0', '0', '', '', 'image_ocr', '4a9fd4ed-652d-4429-95aa-f1fc31d95bc8', '[{"url":"resource://nZHOw-sT3k8VFVcmMomqEw","original_url":"resource://nZHOw-sT3k8VFVcmMomqEw","start_pos":0,"end_pos":0,"caption":"这是一份扫描的合同文件，为**重庆北导科技发展有限公司**的《重点运营车辆服务协议》。协议甲方为手写填写的“重庆星达铜业有限公司”，乙方为重庆北导科技发展有限公司。\n\n主要内容包括：\n- **乙方职责**：按照重庆主管部门要求为甲方车辆安装车载定位监控设备并录入管理平台；免费提供车辆监督管理平台并负责日常维护；提供监控终端维护、技术支持、设备维修与质保及平台免费升级；保障动态监控平台正常运行并对甲方安全管理人员提供技术培训。\n- **甲方职责**：确保车辆信息真实有效，信息变更时及时提交乙方并在监控平台修改。\n\n页面底部印有公司地址（重庆市渝中区石油路1号12栋1103）和联系电话（023-68724666）。","ocr_text":"# 重庆北导科技发展有限公司重点运营车辆服务协议\n\n**甲方：** 重庆星达铜业有限公司\n\n**乙方：** 重庆北导科技发展有限公司\n\n甲、乙双方本着诚信原则，经双方友好协商，就甲方车辆安装车载定位监控设备及后续相关服务事宜达成以下协议：\n\n## 一、乙方职责：\n\n1、乙方按照重庆区域主管部门要求，为甲方下属车辆，安装符合：交通部、重庆市运管局要求的车辆安全监控管理设备，并按照相关要求将企业、车辆信息录入对应管理平台，以便甲方车辆正常办理相关营运手续；\n\n2、乙方为甲方免费提供车辆监督管理平台的使用，并负责对平台进行日常维护；\n\n3、乙方负责提供车辆监控终端的日常维护、技术支持、设备维修与质保以及平台系统的免费升级服务；\n\n4、乙方负责车辆动态监控平台的正常运行，并配合甲方及时解决平台运营过程中出现的问题，并对甲方安全管理人员提供相关技术培训。\n\n## 二、甲方职责：\n\n1、甲方负责确保车辆信息的真实性和有效性。如车辆信息发生变更时，要第一时间把更正后的信息提交给乙方并在监控平台上进行修改；"}]', NULL, NULL, '2026-09-07 07:29:01.99743+00', '2026-09-07 07:29:03.211691+00', NULL, NULL, '', '2', '', '1', '100000766', NULL, '# 重庆北导科技发展有限公司重点运营车辆服务协议
