本合同编号为HT-20260901-001，由重庆星达铜业有限公司（甲方，买方）与重庆办公设备销售有限公司（乙方，卖方）签订。合同内容包括：乙方为甲方供应20台办公电脑及配套设备，总金额100000元（含税），税率为13%。付款方式为合同签订后7日内支付50%，设备验收合格后15日内支付剩余50%，并保留合同金额5%的质保金。乙方应在2026年9月30日前完成交付，履行期限为30天，合同签订地点在重庆市璧山区。若任何一方违约，需支付合同金额10%的违约金。合同自2026年9月1日起生效，有效期至2027年9月1日。', '2', 't', '0', '0', '', '', 'summary', '939353f8-9080-4f9e-8138-9ae5db360f4a', '', NULL, NULL, '2026-09-07 00:47:41.851538+00', '2026-09-07 00:47:41.851538+00', '2026-09-07 00:55:09.363116+00', NULL, '', '0', '', '1', '100000450', NULL, '# Summary
本合同编号为HT-20260901-001，由重庆星达铜业有限公司（甲方，买方）与重庆办公设备销售有限公司（乙方，卖方）签订。合同内容包括：乙方为甲方供应20台办公电脑及配套设备，总金额100000元（含税），税率为13%。付款方式为合同签订后7日内支付50%，设备验收合格后15日内支付剩余50%，并保留合同金额5%的质保金。乙方应在2026年9月30日前完成交付，履行期限为30天，合同签订地点在重庆市璧山区。若任何一方违约，需支付合同金额10%的违约金。合同自2026年9月1日起生效，有效期至2027年9月1日。', '0', 'ready', '', ''),
('8ff3a0ca-79c5-4f2a-af7c-ac316c08eb98', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', 'f2531ec6-33d0-4690-a661-f0bb45b020b6', '### 办公区域保洁服务合同
甲方 （委托方） ： 重庆星达铜业有限公司
乙方 （受托方） ： 重庆洁美保洁服务有限公司
根据 《中华人民共和国民法典》 及相关法律法规， 甲乙双方本着平等自愿、 诚实信用的原则， 经友好协商， 就
一、 项目内容： 办公区域日常保洁服务
二、 合同金额： 人民币48000元 （大写： 见合同附件） 。
三、 履行期限： 自合同签订之日起至项目验收合格之日止。
四、 付款方式： 合同签订后支付30% ， 验收合格后支付剩余70% 。
五、 违约责任： 任何一方违约， 应赔偿守约方因此遭受的全部损失。
六、 争议解决： 因本合同引起的争议， 双方协商解决； 协商不成的， 向甲方所在地人民法院提起诉讼。
七、 本合同一式两份， 甲乙双方各执一份， 自双方签字盖章之日起生效。
甲方 （盖章） ： 重庆星达铜业有限公司
