('d3cefb6f-066c-4e91-98f3-637c20798efd', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '04861ff1-c476-4510-b77e-14115626c6ca', '这是一枚红色的圆形企业公章，印文为“重庆星达铜业有限公司”，中央有一棵红色五角星，下方印有数字编码"5002278078098"。', '0', 't', '0', '0', '', '', 'image_caption', '45b9d049-9ca7-4d7d-bf27-15b514718a98', '[{"url":"resource://AtGZTLXgC54TnmVRK75ziQ","original_url":"resource://AtGZTLXgC54TnmVRK75ziQ","start_pos":0,"end_pos":0,"caption":"这是一枚红色的圆形企业公章，印文为“重庆星达铜业有限公司”，中央有一棵红色五角星，下方印有数字编码\"5002278078098\"。","ocr_text":"重庆星达铜业有限公司\n5002278078098"}]', NULL, NULL, '2026-09-07 00:56:35.713168+00', '2026-09-07 00:56:37.214404+00', '2026-09-07 07:25:12.131119+00', NULL, '', '2', '', '1', '100000491', NULL, '这是一枚红色的圆形企业公章，印文为“重庆星达铜业有限公司”，中央有一棵红色五角星，下方印有数字编码"5002278078098"。', '0', 'ready', '', ''),
('7b7d7b38-7a26-4fd7-bc15-16b514d835df', '10000', 'f0f32eb9-69d8-4cec-8ec3-d2e6014a06b3', '7f2d39ad-1afd-4eb8-b807-34e192f8ca6d', '将 GPS 天线固定在车辆顶部，连接天线馈线至 GPS 主机。
将 GPS 主机固定在驾驶室内，连接电源线和信号线。
连接 GPS 主机与车辆 CAN 总线（如有）。
检查所有连接线是否牢固可靠，确保设备安装稳固。
4. 调试与测试
打开车辆电源，启动 GPS 主机，检查设备是否正常启动。
使用 GPS 测试软件，检查设备定位精度、信号强度等参数是否正常。
检查设备与监管平台的通信连接是否正常，数据上传是否及时准确。
模拟车辆行驶状态，测试设备各项功能是否正常，包括定位、轨迹
