('16c8d432-0c67-4331-ac05-97dd280663b1', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', 'f2531ec6-33d0-4690-a661-f0bb45b020b6', '### 办公区域保洁服务合同
甲方 （委托方） ： 重庆星达铜业有限公司
乙方 （受托方） ： 重庆洁美保洁服务有限公司
根据 《中华人民共和国民法典》 及相关法律法规， 甲乙双方本着平等自愿、 诚实信用的原则， 经友好协商， 就
一、 项目内容： 办公区域日常保洁服务
二、 合同金额： 人民币48000元 （大写： 见合同附件） 。
三、 履行期限： 自合同签订之日起至项目验收合格之日止。
四、 付款方式： 合同签订后支付30% ， 验收合格后支付剩余70% 。
五、 违约责任： 任何一方违约， 应赔偿守约方因此遭受的全部损失。
六、 争议解决： 因本合同引起的争议， 双方协商解决； 协商不成的， 向甲方所在地人民法院提起诉讼。
七、 本合同一式两份， 甲乙双方各执一份， 自双方签字盖章之日起生效。
甲方 （盖章） ： 重庆星达铜业有限公司
法定代表人或授权代表：
____________
乙方 （盖章） ： 重庆洁美保洁服务有限公司
法定代表人或授权代表：
____________
