('78c4f5bd-5591-4c4d-90ef-94a3a15ba2ba', '10000', 'f0f32eb9-69d8-4cec-8ec3-d2e6014a06b3', '7f2d39ad-1afd-4eb8-b807-34e192f8ca6d', '1. 打开浏览器，输入 GPS 监管平台的网址。
2. 输入用户名和密码，点击“登录”按钮。
3. 进入系统主界面。
三、 功能模块
1. 车辆监控
实时监控:查看所有在线车辆的实时位置、速度、方向等信息。
轨迹回放:选择时间段和车辆，回放车辆行驶轨迹。
电子围栏:设置车辆行驶区域，超出区域时系统自动报警。
超速报警:设置车辆行驶速度上限，超速时系统自动报警。
停车报警:设置车辆停车时间上限，停车超时时系统自动报警。
2. 数据统计
车辆统计:统计车辆总数、在线车辆数、离线车辆数等信息。
里程统计:统计车辆行驶里程、平均速度等信息。
油耗统计:统计车辆油耗情况。
报警统计:统计车辆报警次数、类型等信息。
3. 报表管理
生成报表:根据需要生成车辆行驶报表、报警报表等。
