2. 数据统计
车辆统计:统计车辆总数、在线车辆数、离线车辆数等信息。
里程统计:统计车辆行驶里程、平均速度等信息。
油耗统计:统计车辆油耗情况。
报警统计:统计车辆报警次数、类型等信息。
3. 报表管理
生成报表:根据需要生成车辆行驶报表、报警报表等。
