4. 系统设置
用户管理:添加、删除、修改用户信息，设置用户权限。
车辆管理:添加、删除、修改车辆信息，绑定车辆与 GPS 终端。
参数设置:设置系统参数，例如报警阈值、地图显示等。
四、 操作步骤
1. 实时监控
在主界面点击“实时监控”菜单。
地图上显示所有在线车辆的实时位置。
点击车辆图标，查看车辆详细信息，包括车牌号、速度、方向等。
2. 轨迹回放
在主界面点击“轨迹回放”菜单。
选择时间段和车辆。
点击“开始回放”按钮，地图上显示车辆行驶轨迹。
3. 电子围栏
在主界面点击“电子围栏”菜单。
点击“添加围栏”按钮，在地图上绘制围栏区域。
设置围栏名称、类型、报警方式等参数。
点击“保存”按钮，完成围栏设置。
4. 超速报警
在主界面点击“超速报警”菜单。
选择车辆，设置速度上限。
