('6831b7fb-9f05-471d-a5f9-c435921fa148', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '69cde05b-ce88-4696-99ec-b5642642fcaa', '办公设备采购合同
合同编号：HT-20260901-001
甲方（买方）：重庆星达铜业有限公司
统一社会信用代码：91500120MA5XXXXXXX
地址：重庆市璧山区XX工业园
电话：023-XXXXXXXX
开户行：中国工商银行重庆璧山支行
账号：3100XXXXXXXXXXXXXXX
乙方（卖方）：重庆办公设备销售有限公司
统一社会信用代码：91500103MA6YYYYYYY
地址：重庆市九龙坡区XX路XX号
电话：023-YYYYYYYY
开户行：中国建设银行重庆九龙坡支行
账号：5000XXXXXXXXXXXXXXX
一、合同标的
乙方为甲方供应办公电脑及配套设备，标的为「办公电脑及配套设备采购项目」，数量 20
台，单价 5000 元，合同总金额为人民币 100000 元（含税）。税率 13%。
二、付款方式
合同签订后 7 日内甲方支付合同金额的 50%，设备验收合格后 15 日内支付剩余
50%，付款方式为分期付款。质保金为合同金额的 5%。
三、履行期限与地点
乙方应于 2026 年 9 月 30 日前完成交付，履行期限为 30
天。本合同签订地点为重庆市璧山区。
四、违约责任
任何一方违约，应向守约方支付违约金，违约金为合同金额的 10%。
五、签署
本合同签订日期为 2026 年 9 月 1 日，自双方签字盖章之日起生效，有效期至 2027 年 9 月 1
日。
